import type { ComboboxProps } from "../combobox.types";

import { createContext, useContext } from "react";

export interface ComboboxStateContextType {
  as: ComboboxProps["as"];
  value: unknown;
  inputValue: string;
  isControlled: boolean;
  setInputValue: (value: string) => void;
  setValue: (value: unknown) => void;
  showSelectedIndicator?: boolean;
  noResults?: React.ReactNode;
  inputSize?: "sm" | "default";
  placeholder?: string;
  id?: string;
  disabled?: boolean;
  variant?: ComboboxProps["variant"];
  styleSlots?: ComboboxProps["styleSlots"];
  openOnClick?: boolean;
  itemToString: (item: unknown) => string;
  inputRef: React.RefObject<HTMLInputElement | null>;
}

export const ComboboxStateContext = createContext<ComboboxStateContextType | undefined>(undefined);

export const useComboboxState = () => {
  const context = useContext(ComboboxStateContext);
  if (!context) {
    throw new Error("useComboboxState must be used within a Combobox component");
  }
  return context;
};
